-- Monthly flagged gross and transaction activity by transaction type (1) or location label (2). One dimension per call. Source locations are not KYC residence or verified geography.
SELECT * FROM finance.agent_demo_fs.exposure_mix_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY') AND period_key = CASE WHEN CAST({{period_key}} AS INT) = 0 THEN (SELECT MAX(period_key) FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY')) ELSE CAST({{period_key}} AS INT) END AND dimension_code = CAST({{dimension_code}} AS INT) ORDER BY flagged_gross_usd DESC, dimension_value LIMIT 30
